// Data Hazard Detection and Handling (RAW Dependency)
typedef int RegID;
#define REG_ZERO 0

// Abstract representation of instruction moving through a stage
typedef struct {
    RegID rd;
    RegID rs1, rs2;
    bool writes_rd;
    bool active;
} PipelineReg;

// Checks if the instruction entering ID stage depends on
// the result being calculated in the EX stage (1 cycle latency)
bool DataHazard_Stall(PipelineReg EX_I, PipelineReg ID_I) {
    // If EX instruction does not write a result, no hazard
    if (!EX_I.active || !EX_I.writes_rd || EX_I.rd == REG_ZERO) {
        return false;
    }

    // Check dependency (RAW)
    return (EX_I.rd == ID_I.rs1 || EX_I.rd == ID_I.rs2);
}

